<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$id=(int)($_GET['id']??0);$s=$db->prepare('SELECT * FROM leads WHERE id=? LIMIT 1');$s->execute([$id]);$lead=$s->fetch();if(!$lead){http_response_code(404);exit('Lead not found.');}$phone=preg_replace('/\D+/','',(string)($lead['phone']??''));if(str_starts_with($phone,'0'))$phone='234'.substr($phone,1);$message='Hello '.$lead['name'].', this is Distinguished Web Services following up regarding your '.($lead['service']?:'project').' enquiry. We would be happy to discuss your requirements and next steps.';$wa=$phone?'https://wa.me/'.$phone.'?text='.rawurlencode($message):'';$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lead Communication</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:700px"><div class="card border-0 shadow-sm p-4"><h1 class="h3"><?=$esc($lead['name'])?></h1><p class="text-muted"><?=$esc($lead['email'])?> · <?=$esc($lead['phone'])?></p><div class="d-grid gap-2"><a class="btn btn-dark" href="mailto:<?=$esc($lead['email'])?>?subject=<?=rawurlencode('Following up on your '.$lead['service'].' enquiry')?>">Open Email</a><?php if($wa):?><a class="btn btn-success" target="_blank" rel="noopener" href="<?=$esc($wa)?>">Open WhatsApp</a><?php else:?><div class="alert alert-warning">No phone number is available for WhatsApp.</div><?php endif;?></div><hr><h2 class="h6">Suggested WhatsApp message</h2><p class="bg-light border rounded p-3"><?=$esc($message)?></p><a href="lead.php?id=<?=$id?>" class="btn btn-outline-secondary">Back to Lead</a></div></main></body></html>